const mb = $("#mb"),
  lk = $("#links");
mb.onclick = () => {
  const o = lk.classList.toggle("open");
  mb.setAttribute("aria-expanded", o);
};
lk.addEventListener("click", (e) => {
  if (e.target.closest("a")) {
    lk.classList.remove("open");
    mb.setAttribute("aria-expanded", "false");
  }
});
const navA = [...lk.querySelectorAll("a:not(.btn)")];
const io = new IntersectionObserver(
  (es) =>
    es.forEach((en) => {
      if (en.isIntersecting) {
        navA.forEach((a) =>
          a.classList.toggle(
            "on",
            a.getAttribute("href") === "#" + en.target.id ||
              (en.target.id === "skills" &&
                a.getAttribute("href") === "#projects"),
          ),
        );
      }
    }),
  { rootMargin: "-40% 0px -55% 0px" },
);
document.querySelectorAll("main section[id]").forEach((s) => io.observe(s));

const rv = new IntersectionObserver(
  (es) =>
    es.forEach((e) => {
      if (e.isIntersecting) {
        e.target.classList.add("in");
        rv.unobserve(e.target);
      }
    }),
  { threshold: 0.06 },
);
document.querySelectorAll("main section:not(.hero) .wrap").forEach((w) => {
  w.classList.add("reveal");
  rv.observe(w);
});
const pg = $("#prog");
addEventListener(
  "scroll",
  () => {
    const h = document.documentElement;
    pg.style.width =
      (h.scrollTop / (h.scrollHeight - h.clientHeight || 1)) * 100 + "%";
  },
  { passive: true },
);
const hd = $("header.nav");
addEventListener("scroll", () => hd.classList.toggle("sc", scrollY > 8), {
  passive: true,
});
if (!matchMedia("(prefers-reduced-motion:reduce)").matches)
  document.querySelectorAll(".proof b").forEach((b) => {
    const n = +b.textContent;
    if (!n) return;
    const t0 = performance.now();
    (function f(t) {
      const k = Math.min(1, (t - t0) / 900);
      b.textContent = Math.round(n * (1 - Math.pow(1 - k, 3)));
      if (k < 1) requestAnimationFrame(f);
    })(t0);
  });
$("#cf").addEventListener("submit", (e) => {
  e.preventDefault();
  const f = e.target,
    m = $("#fm"),
    v = (n) => f[n].value.trim();
  m.className = "msg";
  if (!v("n") || !v("e") || !v("s") || !v("m")) {
    m.className = "msg err";
    m.textContent = "Please fill in every field.";
    return;
  }
  if (!/^\S+@\S+\.\S+$/.test(v("e"))) {
    m.className = "msg err";
    m.textContent = "Enter a valid email address, such as name@example.com.";
    return;
  }
  if (!CONFIG.email) {
    m.className = "msg err";
    m.textContent =
      "No destination email is set yet. Add your address to CONFIG.email.";
    return;
  }
  location.href =
    "mailto:" +
    CONFIG.email +
    "?subject=" +
    encodeURIComponent(v("s")) +
    "&body=" +
    encodeURIComponent(v("m") + "\n\n— " + v("n") + " (" + v("e") + ")");
  m.className = "msg ok";
  m.textContent =
    "Your email app should open with the message ready. Press send there to deliver it.";
});
